async function tls(scope:Scope, socket:Socket, ca:Buffer, host="proof.localhost", diagnostic?:TlsDiagnostic): Promise<TLSSocket> {
  assert(!scope.stopped,"PROBE_SCOPE_CLOSED");
  if (diagnostic) diagnostic.phases|=1; // Original TCP is held.
  const secure = connectTls({socket,servername:host,ca,rejectUnauthorized:true,ALPNProtocols:["http/1.1"]});
  if (diagnostic) diagnostic.phases|=2;
  own(scope,secure);
  try {
    await until(new Promise<void>((yes,no) => {
      secure.once("secureConnect",() => {if (diagnostic) diagnostic.phases|=4;yes();});
      secure.once("error",(error:unknown) => {
        if (diagnostic) diagnostic.phases|=32;
        observeTlsError(diagnostic,error);no(error);
      });
    }),performance.now()+2000,"PROBE_TLS_TIMEOUT");
  } catch (error) {
    if (diagnostic) diagnostic.phases|=64;
    observeTlsError(diagnostic,error);throw error;
  }
  if (diagnostic) diagnostic.phases|=8;
  assert(secure.authorized && !checkServerIdentity(host,secure.getPeerCertificate()),"PROBE_TLS_IDENTITY");
  if (diagnostic) diagnostic.phases|=16;
  return secure;
}

